schematic.netlist:
inverting, input grounded
R1 0 inv {Rin:spice}
R2 inv out {Rf:spice}
X1 0 inv out OA
.model OA OPAMP(A=1e5)

sim.netlist:
Inverting amplifier at one frequency
V1 in 0 AC 1
R1 in inv {Rin:spice}
R2 inv out {Rf:spice}
X1 0 inv out OA
.model OA OPAMP(A=1e5 GBW={GBW:spice} VPOS=15 VNEG=-15)
.ac lin 1 {f:spice} {f:spice}

schematic.netlist:
non-inverting
V1 in 0 1
X1 in inv out OA
RF out inv {Rf:spice}
RG inv 0 {Rg:spice}
.model OA OPAMP(A=1e5)

inverting stage and anti-alias filter
V1 in 0 AC 1
R1 in inv {Rin:spice}
R2 inv out {Rf:spice}
X1 0 inv out OA
R3 out adc {R:spice}
C1 adc 0 {C:spice}
.model OA OPAMP(A=1e5 GBW={GBW:spice})
